/* The Grounded Readings Library, group gpray (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["gpray"] = [{"id":"pray-hapgood-blessed-is-the-way","title":"Blessed Is the Way","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"chant","occasion":["funeral","dying","grief","comfort"],"text":"Blessed is the way in which thou shalt walk to-day, O soul; for a place of rest is prepared for thee.","note":"Sung before the Epistle at the Orthodox funeral, as the soul sets out on its way.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/388"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-earthly-sweetness","title":"From the Funeral Hymns of Saint John of Damascus","by":"Saint John of Damascus","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"hymn","occasion":["funeral","grief","comfort"],"text":"What earthly sweetness remaineth unmixed with grief? What glory standeth immutable on earth? All things are but shadows most feeble, but most deluding dreams: yet one moment only, and Death shall supplant them all. But in the light of thy countenance, O Christ, and in the sweetness of thy beauty, give rest unto him (her) whom thou hast chosen: forasmuch as thou lovest mankind.","note":"Sung near the end of the Orthodox funeral, before the Beatitudes and the last kiss.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/386"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain. Saint John of Damascus died about 749."},{"id":"pray-hapgood-thy-creating-command","title":"Thy Creating Command","by":"Saint John of Damascus","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"hymn","occasion":["funeral","grief","comfort"],"text":"Thy creating command was my origin and my foundation: for thy pleasure it was out of nature visible and invisible to fashion me, a living creature. From the earth thou didst shape my body, and didst give me a soul by thy divine and quickening breath. Wherefore, O Lord, give rest to thy servant in the land of the living, in the habitations of the Just.","note":"One of the eight funeral hymns of Saint John of Damascus, sung at the Orthodox funeral.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/387"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain. Saint John of Damascus died about 749."},{"id":"pray-hapgood-choir-of-the-saints","title":"The Choir of the Saints Have Found the Fountain of Life","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"hymn","occasion":["funeral","grief","hope"],"text":"The Choir of the Saints have found the Fountain of Life and the Door of Paradise. May I also find the right way, through repentance. I am a lost sheep. Call me, O Saviour, and save me.\n\nYe who have trod the narrow way most sad; all ye who, in life, have taken upon you the Cross as a yoke, and have followed Me through faith, draw near: Enjoy ye the honours and the crowns which I have prepared for you.\n\nGive rest, O Lord, to the soul of thy servant, and establish him (her) in Paradise. Where the choirs of the Saints, O Lord, and of the Just, shine like the stars of heaven, give rest to thy servant who hath fallen asleep, regarding not all his (her) transgressions.","note":"From the hymns sung with Psalm 119 at the Orthodox funeral, each verse answered by Blessed art thou, O Lord: teach me thy statutes.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/379"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-shadow-and-a-dream","title":"Life Is But a Shadow and a Dream","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"hymn","occasion":["funeral","grief"],"text":"Of a truth, all things are vanity, and life is but a shadow and a dream. For in vain doth every one who is born of earth disquiet himself, as saith the Scriptures. When we have acquired the world, then do we take up our abode in the grave, where kings and beggars lie down together. Wherefore, O Christ our God, give rest to thy servant departed this life; forasmuch as thou lovest mankind.","note":"The sitting hymn after the third ode of the Orthodox funeral canon.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/382"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-sea-of-life","title":"The Sea of Life","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"hymn","occasion":["funeral","comfort","peace"],"text":"Forasmuch as I behold the sea of life surging high with the tempest of temptations, I have fled to thy tranquil haven and cry aloud unto thee: Lead thou my life forth from corruption, O Most Merciful One.","note":"The theme song of the sixth ode of the Orthodox funeral canon, a cry for a tranquil haven.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/383"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-land-of-the-living","title":"May Christ Give Thee Rest in the Land of the Living","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"blessing","occasion":["funeral","grief","blessing"],"text":"O thou who rulest over souls and bodies, in whose hand is our breath, the Consolation of the afflicted: In the land of the Just give rest unto thy servant whom thou hast taken from us.\n\nMay Christ give thee rest in the land of the living, and open unto thee the gates of Paradise, and make thee a citizen of his kingdom; and give thee remission of those things wherein thou in life hast sinned, O thou who lovest Christ.","note":"Sung between the Beatitudes at the Orthodox funeral, spoken to the one who has died.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/387"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-who-alone-hast-immortality","title":"Who Alone Hast Immortality","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"prayer","occasion":["funeral","grief"],"text":"O Master, Lord our God, who alone hast immortality, and dwellest in light unapproachable; who slayest and makest alive; who castest down into Hell, and again raisest up; Thou in wisdom hast created man, and returnest him to the earth again, exacting the spiritual debt: Receive, we beseech thee, the soul of thy servant, and grant him rest in the bosom of Abraham, and Isaac, and Jacob; and give him the crown of thy righteousness, the portion of the saved, in the glory of thine elect. And for those things which in this world he hath wrought for thy Name's sake, may he receive a rich reward in the mansions of thy Saints; through the grace, and bounties, and love toward mankind of thine Only-begotten Son, our Lord Jesus Christ. Amen.\n\nTo-day part I from my kinsfolk, and flee unto thee, the Only Sinless One. In the mansions of the righteous with thine elect grant me rest.","note":"A prayer from the Orthodox burial of a priest, with the short hymn sung after it.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/396"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-fleeting-dream","title":"We Are a Fleeting Dream","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"hymn","occasion":["funeral","grief"],"text":"Forasmuch as we all are constrained to that same dread abode, and shall hide ourselves beneath a gravestone like to this, and shall ourselves shortly turn to dust, let us implore of Christ rest for him who hath been translated hence. For such is our life here, brethren, a mockery upon the earth; when we have no being, to receive it, and when we have being to dissolve into corruption. We are a fleeting dream; a breath which endureth not; the flight of a passing bird; a ship which leaveth no trace upon the sea. Wherefore, let us cry aloud unto the King Immortal; Deem him worthy of thy bliss never-ending, O Lord.","note":"A sitting hymn from the Orthodox burial of a priest, on how brief and precious life is.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/396"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-hope-of-the-hopeless","title":"O Hope of the Hopeless","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"prayer","occasion":["dying","comfort","peace"],"text":"O Master, Lord our God Almighty, who willest that all men should be saved and should come to a knowledge of the truth; who desirest not the death of a sinner, but that he should turn again and be saved: We pray thee and beseech thee, deliver thou the soul of thy servant, N., from every bond, free it from every curse. For thou art he who delivereth them that are bound, and guideth aright them that are cast down, O Hope of the hopeless. Wherefore, O Master, command that the soul of thy servant, N., may depart in peace, and may rest in thine everlasting mansions with all thy Saints; through thine Only-begotten Son, with whom thou art blessed, together with thine all-holy, and good, and life-giving Spirit, now, and ever, and unto ages of ages. Amen.","note":"Said by the priest at the bedside as a soul is parting from the body.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/367"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-naming-of-a-child","title":"At the Naming of a Child","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"prayer","occasion":["birth","blessing"],"text":"O Lord our God, we pray unto thee, and we beseech thee, and implore thee, that the light of thy countenance may be shown upon this thy servant, N.; and that the cross of thine Only-begotten Son may be graven in his (her) heart, and in his (her) thoughts: that he (she) may flee from the vanity of the world and from every evil snare of the enemy, and may follow after thy commandments. And grant, O Lord, that thy holy Name may remain unrejected by him (her); and that he (she) may be united, in due time, to thy holy Church; and that the dread Sacraments of thy Christ may be administered unto him (her): That, having lived according to thy commandments, and preserved without flaw the seal, he (she) may receive the bliss of the elect in thy kingdom; through the grace and love towards mankind of thine Only-begotten Son, with whom also thou art blessed, together with thine all-holy, and good, and life-giving Spirit, now, and ever, and unto ages of ages. Amen.","note":"Said over an infant on the eighth day after birth, when the child receives a name.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/268"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-angel-fellow-traveller","title":"Send Thine Angel as a Fellow-Traveller","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"blessing","occasion":["blessing","daily"],"text":"O Christ, who art the Way and the Truth, send now thine Angel as a fellow-traveller to thy servant(s), preserving him (her, them) like Tobias of old, and guarding him (her, them) unharmed of every evil thing, and in all prosperity, unto thy glory: through the prayers of the Birth-giver of God, O thou who alone lovest mankind.\n\nO Saviour, who didst accompany Luke and Cleopas unto Emmaus, accompany thou now also thy servant who is (servants who are) minded to travel, delivering him (her, them) from every evil assault: For thou canst do all things whatsoever thou wilt, in that thou lovest mankind.","note":"Two hymns from the Orthodox rite of blessing for a journey.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/525"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-wesley-make-me-what-thou-wilt","title":"From the Covenant: Make Me What Thou Wilt","by":"John Wesley, from Joseph Alleine","year":1780,"trad":["methodist","christian"],"denom":["wesleyan"],"type":"prayer","occasion":["daily","blessing","season"],"text":"Make me what thou wilt, Lord, and set me where thou wilt: let me be a vessel of silver or gold, or a vessel of wood or stone, so I be a vessel of honour: of whatsoever form or metal, whether higher or lower, finer or coarser, I am content; if I be not the head, or the eye, or the ear, one of the nobler and more honourable instruments thou wilt employ, let me be the hand, or the foot, one of the most laborious, and lowest, and most contemptible of all the Servants of my Lord, let my dwelling be on the dunghill, my portion in the wilderness, my name and lot be amongst the hewers of wood, or drawers of water, among the door-keepers of thy house; any where, where I may be serviceable; I put myself wholly into thy hands: put me to what thou wilt, rank me with whom thou wilt; put me to doing, put me to suffering, let me be employed for thee, or laid aside for thee, exalted for thee or trodden under foot for thee; let me be full, let me be empty, let me have all things, let me have nothing, I freely and heartily resign all to thy pleasure and disposal.","note":"The words of yielding at the heart of the Methodist Covenant Service, held at the New Year; the later Covenant Prayer grew from them.","voice":"brian","source":{"name":"John Wesley, Directions for Renewing Our Covenant with God (1780; 1787 printing), Internet Archive","url":"https://archive.org/details/bim_eighteenth-century_directions-for-renewing-_wesley-john_1787"},"rights":"pd","pd":"First published 1780 (Wesley adapting Joseph and Richard Alleine); Wesley died 1791; public domain."},{"id":"pray-wesley-covenant-friend","title":"From the Covenant: Thou Art Now Become My Covenant Friend","by":"John Wesley, from Joseph Alleine","year":1780,"trad":["methodist","christian"],"denom":["wesleyan"],"type":"prayer","occasion":["gratitude","season","blessing"],"text":"And now, glory be to thee, O God the Father, whom I shall be bold from this day forward to look upon as my God and Father; that ever thou shouldst find out such a way for the recovery of undone Sinners. Glory be to thee, O God the Son, who hast loved me, and washed me from my sins in thine own blood, and art now become my Saviour and Redeemer. Glory be to thee, O God the Holy Ghost, who by the Finger of thine almighty power hast turned about my heart from Sin to God.\n\nO dreadful Jehovah, the Lord God Omnipotent, Father, Son, and Holy Ghost, Thou art now become my Covenant-Friend, and I through thy infinite grace, am become thy Covenant-Servant. Amen. So be it. And the Covenant which I have made on earth, let it be ratified in heaven.","note":"The closing praise of the covenant said at the Methodist Covenant Service.","voice":"brian","source":{"name":"John Wesley, Directions for Renewing Our Covenant with God (1780; 1787 printing), Internet Archive","url":"https://archive.org/details/bim_eighteenth-century_directions-for-renewing-_wesley-john_1787"},"rights":"pd","pd":"First published 1780 (Wesley adapting Joseph and Richard Alleine); Wesley died 1791; public domain."},{"id":"pray-woolman-principle-which-is-pure","title":"A Principle Which Is Pure","by":"John Woolman","year":1762,"trad":["quaker","christian","all"],"type":"reflection","occasion":["peace","daily","hope"],"text":"There is a principle, which is pure, placed in the human mind, which in different places and ages hath had different names; it is, however, pure, and proceeds from God. It is deep, and inward, confined to no forms of religion, nor excluded from any, where the heart stands in perfect sincerity. In whomsoever this takes root, and grows, of what nation soever, they become brethren, in the best sense of the expression.","note":"Woolman on the pure principle in every heart, from his second essay on keeping slaves, often read in Friends meetings and interfaith gatherings.","voice":"brian","source":{"name":"The Works of John Woolman, in Two Parts (Philadelphia, 1774), Considerations on Keeping Negroes, Part Second, Internet Archive","url":"https://archive.org/details/worksofjohnwoolm00wool_2"},"rights":"pd","pd":"First published 1762; Woolman died 1772; public domain.","denom":[]},{"id":"pray-penington-our-life-is-love","title":"Our Life Is Love","by":"Isaac Penington","year":1667,"trad":["quaker","christian"],"type":"reflection","occasion":["peace","forgiveness","home","daily"],"text":"Our life is love, and peace, and tenderness, and bearing one with another, and forgiving one another, and not laying accusations one against another; but praying one for another, and helping one another up with a tender hand, if there has been any slip or fall, and waiting till the Lord gives sense and repentance, if sense and repentance in any be wanting. Oh, wait to feel this spirit, and to be guided to walk in this spirit, that ye may enjoy the Lord in sweetness, and walk sweetly, meekly, tenderly, peaceably, and lovingly one with another.","note":"From a letter Penington wrote to Friends in Amersham in 1667, read today wherever a community seeks gentleness with one another.","voice":"brian","source":{"name":"Letters of Isaac Penington (Philadelphia, 1859), Letter XXI, Internet Archive","url":"https://archive.org/details/peningtonsletter00peniuoft"},"rights":"pd","pd":"Written 1667, first published 1796; Penington died 1679; public domain.","denom":[]},{"id":"pray-lds-come-come-ye-saints","title":"Come, Come, Ye Saints","by":"William Clayton","year":1846,"trad":["lds","christian"],"type":"hymn","occasion":["hope","comfort","funeral"],"text":"Come, come, ye saints, no toil nor labour fear,\nBut with joy wend your way,\nThough hard to you this journey may appear,\nGrace shall be as your day.\n'Tis better far for us to strive,\nOur useless cares from us to drive;\nDo this, and joy your hearts will swell,\nAll is well, all is well.\n\nWhy should we mourn or think our lot is hard?\n'Tis not so, all is right;\nWhy should we think to earn a great reward,\nIf we now shun the fight?\nGird up your loins, fresh courage take,\nOur God will never us forsake;\nAnd soon we'll have this tale to tell:\nAll is well, all is well.\n\nWe'll find the place which God for us prepared,\nFar away in the West;\nWhere none shall come to hurt nor make afraid,\nThere the Saints will be blest.\nWe'll make the air with music ring,\nShout praises to our God and King;\nAbove the rest these words we'll tell,\nAll is well, all is well.\n\nAnd should we die before our journey's through,\nHappy day, all is well;\nWe then are free from toil, and sorrow too;\nWith the just we shall dwell;\nBut if our lives are spar'd again,\nTo see the Saints their rest obtain,\nOh, how we'll make this chorus swell,\nAll is well, all is well.","note":"Written on the trek west in 1846 and sung in Latter-day Saint homes and services ever since, including at funerals.","voice":"brian","source":{"name":"Sacred Hymns and Spiritual Songs for the Church of Jesus Christ of Latter-day Saints (Liverpool, 1851), Hymn 46, Internet Archive","url":"https://archive.org/details/sacredhymnsspiri00chur_0"},"rights":"pd","pd":"Written 1846, printed 1851; Clayton died 1879; public domain.","denom":[]},{"id":"pray-newman-definite-service","title":"Some Definite Service","by":"John Henry Newman","year":1893,"trad":["catholic","christian"],"type":"reflection","occasion":["hope","daily","comfort"],"text":"God has created me to do Him some definite service; He has committed some work to me which He has not committed to another. I have my mission: I never may know it in this life, but I shall be told it in the next. Somehow I am necessary for His purposes, as necessary in my place as an Archangel in his. If, indeed, I fail, He can raise another, as He could make the stones children of Abraham. Yet I have a part in this great work; I am a link in a chain, a bond of connexion between persons. He has not created me for naught. I shall do good, I shall do His work; I shall be an angel of peace, a preacher of truth in my own place, while not intending it, if I do but keep His commandments and serve Him in my calling.\n\nTherefore I will trust Him. Whatever, wherever I am, I can never be thrown away. If I am in sickness, my sickness may serve Him; in perplexity, my perplexity may serve Him; if I am in sorrow, my sorrow may serve Him. My sickness, or perplexity, or sorrow may be necessary causes of some great end, which is quite beyond us. He does nothing in vain; He may prolong my life, He may shorten it; He knows what He is about. He may take away my friends, He may throw me among strangers, He may make me feel desolate, make my spirits sink, hide the future from me, still He knows what He is about.\n\nO Adonai, O Ruler of Israel, Thou that guidest Joseph like a flock, O Emmanuel, O Sapientia, I give myself to Thee. I trust Thee wholly. Thou art wiser than I, more loving to me than I myself. Deign to fulfil Thy high purposes in me whatever they be, work in and through me. I am born to serve Thee, to be Thine, to be Thy instrument. Let me be Thy blind instrument. I ask not to see, I ask not to know, I ask simply to be used.","note":"From a meditation Newman wrote in 1848, read for anyone wondering what their life is for.","voice":"brian","source":{"name":"Meditations and Devotions of the Late Cardinal Newman (1893), Meditations on Christian Doctrine, Hope in God the Creator, Internet Archive","url":"https://archive.org/details/a2514634smrn00newmuoft"},"rights":"pd","pd":"Written 1848, published 1893; Newman died 1890; public domain.","denom":[]},{"id":"pray-newman-support-us","title":"Support Us All the Day Long","by":"John Henry Newman","year":1843,"trad":["catholic","episcopal","christian"],"type":"prayer","occasion":["evening","funeral","peace","comfort"],"text":"May He support us all the day long, till the shades lengthen, and the evening comes, and the busy world is hushed, and the fever of life is over, and our work is done! Then in His mercy may He give us a safe lodging, and a holy rest, and peace at the last!","note":"The close of a sermon Newman preached in 1843, now one of the best loved evening and funeral prayers.","voice":"brian","source":{"name":"John Henry Newman, Sermons Bearing on Subjects of the Day (1843), Sermon XX, Wisdom and Innocence, Internet Archive","url":"https://archive.org/details/a600660200newmuoft"},"rights":"pd","pd":"Published 1843; Newman died 1890; public domain.","denom":[]},{"id":"pray-newman-shine-through-me","title":"Shine Through Me","by":"John Henry Newman","year":1893,"trad":["catholic","christian"],"type":"prayer","occasion":["morning","daily","gratitude"],"text":"Stay with me, and then I shall begin to shine as Thou shinest: so to shine as to be a light to others. The light, O Jesus, will be all from Thee. None of it will be mine. No merit to me. It will be Thou who shinest through me upon others. O let me thus praise Thee, in the way which Thou dost love best, by shining on all those around me. Give light to them as well as to me; light them with me, through me. Teach me to show forth Thy praise, Thy truth, Thy will. Make me preach Thee without preaching, not by words, but by my example and by the catching force, the sympathetic influence, of what I do, by my visible resemblance to Thy saints, and the evident fulness of the love which my heart bears to Thee.","note":"From Newman's meditation Jesus the Light of the Soul, prayed by people who hope to carry light to others.","voice":"brian","source":{"name":"Meditations and Devotions of the Late Cardinal Newman (1893), Jesus the Light of the Soul, Internet Archive","url":"https://archive.org/details/meditationsandd00newmgoog"},"rights":"pd","pd":"Published 1893; Newman died 1890; public domain.","denom":[]},{"id":"pray-raccolta-adoring-thy-last-breath","title":"Jesus, While Adoring Thy Last Breath","by":"Traditional","tr":"Ambrose St John","year":1902,"trad":["catholic","christian"],"type":"prayer","occasion":["dying","comfort","peace"],"text":"Jesus, while adoring thy last breath, I pray Thee to receive mine. In the uncertainty whether I shall have the command of my senses, when I shall depart out of this world, I offer Thee from this moment my agony and all the pains of my passing away. Thou art my Father and my Saviour, and I give back my soul into thy hands. I desire that my last moment may be united to the moment of thy death, and that the last beat of my heart may be an act of pure love of Thee. Amen.","note":"A prayer for a happy death, said by the sick and by those keeping watch with them.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/103"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Prayer indulgenced 1902.","denom":[]},{"id":"pray-raccolta-spiritual-communion","title":"An Act of Spiritual Communion","by":"Saint Alphonsus Liguori","tr":"Ambrose St John","year":1910,"trad":["catholic","christian"],"type":"prayer","occasion":["daily","comfort","healing"],"text":"My Jesus, I believe that Thou art in the Blessed Sacrament. I love Thee above everything, and I long for Thee in my soul. Since I cannot now receive Thee sacramentally, come at least spiritually into my heart. As though Thou wert already come, I embrace Thee and unite myself entirely to Thee; allow me not to be separated from Thee.\n\nJesus, my good, my sweet love,\nWound, inflame this heart of mine.\nSo that it may be always and all on fire for Thee.","note":"Said by those who long for Communion but cannot receive it, such as the homebound and the sick.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/84"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Saint Alphonsus died 1787.","denom":[]},{"id":"pray-raccolta-consecration-of-the-family","title":"Consecration of the Family to the Sacred Heart","by":"Traditional","tr":"Ambrose St John","year":1908,"trad":["catholic","christian"],"type":"prayer","occasion":["home","blessing","daily"],"text":"Sacred Heart of Jesus, who didst manifest to Blessed Margaret Mary the desire of reigning in Christian families, we to-day wish to proclaim thy most complete regal dominion over our own. We would live in future with thy life, we would cause to flourish in our midst those virtues to which Thou hast promised peace here below, we would banish far from us the spirit of the world which Thou hast cursed; and Thou shalt reign, over our minds in the simplicity of our faith, and over our hearts by the whole-hearted love with which they shall burn for Thee, the flame of which we shall keep alive by the frequent reception of thy divine Eucharist.\n\nDeign, O divine Heart, to preside over our assemblings, to bless our enterprises, both spiritual and temporal, to dispel our cares, to sanctify our joys, to alleviate our sufferings. If ever one or other of us should have the misfortune to afflict Thee, remind him, O Heart of Jesus, that Thou art good and merciful to the penitent sinner. And when the hour of separation strikes, when death shall come to cast mourning into our midst, we will all, both those who go and those who stay, be submissive to thy eternal decrees. We will console ourselves with the thought that a day will come when the entire family, reunited in Heaven, can sing for ever thy glories and thy mercies.\n\nMay the immaculate heart of Mary and the glorious Patriarch, St Joseph, present this consecration to Thee, and keep it in our minds all the days of our life. All glory to the Heart of Jesus, our King and our Father.","note":"Said by a household gathered together, often when an image of the Sacred Heart is set up in the home.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/147"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Consecration approved 1908.","denom":[]},{"id":"pray-raccolta-saint-raphael","title":"Prayer to Saint Raphael","by":"Traditional","tr":"Ambrose St John","year":1910,"trad":["catholic","christian"],"type":"prayer","occasion":["healing","blessing","comfort"],"text":"Glorious Archangel, St Raphael, great Prince of the heavenly court, illustrious for thy gifts of wisdom and grace, guide of those who journey by land or sea, consoler of the afflicted, and refuge of sinners; I beg thee to assist me in all my needs and in all the sufferings of this life, as once thou didst help the young Tobias on his travels. And because thou art the medicine of God, I humbly pray thee to heal the many infirmities of my soul, and the ills which afflict my body, if it be for my greater good. I specially ask of thee an angelic purity which may fit me to be the temple of the Holy Spirit. Amen.","note":"Said before a journey and in sickness, since Raphael guided Tobias and his name means God heals.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/266"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain.","denom":[]},{"id":"pray-raccolta-alphonsus-night","title":"Before Sleep","by":"Saint Alphonsus Liguori","tr":"Ambrose St John","year":1893,"trad":["catholic","christian"],"type":"prayer","occasion":["evening","gratitude","peace"],"text":"Jesus Christ, my God, I adore Thee and I thank Thee for the many favours Thou hast bestowed on me this day. I offer Thee my sleep and all the moments of this night, and I pray Thee to preserve me from sin. Therefore I place myself in thy most sacred side, and under the mantle of our blessed Lady my Mother. May the holy angels assist me and keep me in peace, and may thy blessing be upon me.","note":"Said before going to rest at night.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/395"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Saint Alphonsus died 1787.","denom":[]},{"id":"pray-raccolta-benefactors","title":"For All Who Do Us Good","by":"Traditional","tr":"Ambrose St John","year":1892,"trad":["catholic","christian"],"type":"prayer","occasion":["gratitude","daily"],"text":"Reward, O Lord, with eternal life all those who do us good for thy name's sake. Amen.","note":"A short prayer of thanks for benefactors, often said as a grace after meals.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/395"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain.","denom":[]},{"id":"pray-raccolta-pity-the-dying","title":"Heart of Jesus, Pity the Dying","by":"Traditional","tr":"Ambrose St John","year":1910,"trad":["catholic","christian"],"type":"prayer","occasion":["dying","comfort"],"text":"Most merciful Jesus, Lover of souls: I pray Thee, by the agony of thy most Sacred Heart, and by the sorrows of thy Immaculate Mother, cleanse in thine own Blood the sinners of the whole world who are now in their agony and to die this day. Amen.\n\nHeart of Jesus, once in agony, pity the dying.","note":"Said each day for all who are dying, especially those who will die today.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/133"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain.","denom":[]},{"id":"pray-raccolta-to-thee-blessed-joseph","title":"To Thee, O Blessed Joseph","by":"Pope Leo XIII","tr":"Ambrose St John","year":1889,"trad":["catholic","christian"],"type":"prayer","occasion":["home","comfort","dying"],"text":"To thee, O blessed Joseph, do we fly in our tribulation, and having implored the help of thy most holy spouse, we confidently crave thy patronage also. Through that charity which bound thee to the Immaculate Virgin Mother of God, and through the paternal love with which thou didst embrace the Child Jesus, we humbly beseech thee graciously to regard the inheritance which Jesus Christ hath purchased by his Blood, and with thy power and strength to aid us in our necessities.\n\nO most watchful Guardian of the Divine Family, defend the chosen children of Jesus Christ; O most loving Father, ward off from us every contagion of error and corrupting influence; O our most mighty protector, be propitious to us and from Heaven assist us in this our struggle with the power of darkness; and, as once thou didst rescue the Child Jesus from deadly peril, so now protect God's holy Church from the snares of the enemy and from all adversity: shield, too, each one of us by thy constant protection, so that, supported by thine example and thine aid, we may be able to live piously, to die holily, and to obtain eternal happiness in Heaven. Amen.","note":"Leo XIII's prayer to Saint Joseph, said after the Rosary in October and by families asking for his protection.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/281"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Prayer written 1889; Leo XIII died 1903.","denom":[]},{"id":"pray-raccolta-christian-family","title":"From the Prayer for the Christian Family","by":"Traditional","tr":"Ambrose St John","year":1889,"trad":["catholic","christian"],"type":"prayer","occasion":["home","blessing"],"text":"God of bounty and of mercy, to thy almighty protection we commend our home, our family and all we possess. Bless us all, as Thou didst bless the Holy Family at Nazareth.","note":"A blessing on the home and household, said by the family together.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/393"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain.","denom":[]},{"id":"pray-raccolta-give-peace","title":"Give Peace, O Lord, in Our Days","by":"Traditional","tr":"Ambrose St John","year":1848,"trad":["catholic","christian"],"type":"prayer","occasion":["peace"],"text":"Give peace, O Lord, in our days; for there is none other that fighteth for us, but only Thou, our God.\n\nLet there be peace in thy strength, O Lord. And plenty in thy strong places.","translit":"Da pacem, Domine, in diebus nostris.","note":"The ancient antiphon Da Pacem, sung or said in times of conflict and for peace in the world.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/17"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Antiphon from the early Middle Ages.","denom":[]},{"id":"pray-raccolta-aquinas-before-study","title":"Before Study","by":"Saint Thomas Aquinas","tr":"Ambrose St John","year":1879,"trad":["catholic","christian"],"type":"prayer","occasion":["daily","morning"],"text":"O merciful God, grant that I may eagerly desire, carefully search out, truthfully acknowledge, and ever perfectly fulfil all things which are pleasing to Thee, to the praise and glory of thy Name. Amen.","note":"Said before study, class, or any work of the mind.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/46"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Aquinas died 1274.","denom":[]},{"id":"pray-raccolta-holy-family","title":"In Honour of the Holy Family","by":"Pope Leo XIII","tr":"Ambrose St John","year":1897,"trad":["catholic","christian"],"type":"prayer","occasion":["home","dying","daily"],"text":"Grant us, O Lord Jesus, faithfully to imitate the examples of thy Holy Family, so that in the hour of our death, in the company of thy glorious Virgin Mother and St Joseph, we may deserve to be received by Thee into eternal tabernacles.","note":"A short family prayer asking to live as the Holy Family lived and to be welcomed home at the end.","voice":"brian","source":{"name":"The Raccolta, or Collection of Indulgenced Prayers and Good Works, tr. Ambrose St John (1910 edition), Internet Archive","url":"https://archive.org/details/theraccoltaorcol00unknuoft/page/59"},"rights":"pd","pd":"This English translation printed 1910 (St John died 1875); public domain. Prayer indulgenced 1897.","denom":[]},{"id":"pray-chain-about-to-depart","title":"For Those About to Depart This Life","by":"William Knight","year":1913,"trad":["christian","all"],"type":"prayer","occasion":["dying","peace","comfort"],"text":"We commend unto Thee all those about to depart this life, beseeching Thee to grant unto them the spirit of tranquillity and trustfulness. May they put their hope in Thee, and having passed through the valley of the shadow in peace, may they enter into the rest that remaineth for the people of God; through Jesus Christ our Lord. Amen.","note":"A prayer for the dying and those keeping vigil, asking for a spirit of tranquillity and trust.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/212"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Knight died 1916; public domain.","denom":[]},{"id":"pray-chain-holy-paraclete","title":"Holy Paraclete, Sweetest Consolation","by":"Saint Anselm","year":1913,"trad":["christian","catholic"],"type":"prayer","occasion":["grief","comfort"],"text":"O Holy Paraclete, sweetest Consolation of the sorrowful, gracious Spirit, come down at this time with Thy mighty power into the depths of our hearts. Gladden there with Thy brightness every dark retreat, and enrich all with the dew of Thine abundant comfort. Kindle our inward parts with holy fervour, that the incense of our prayers and praises may ever go up to Thee, O our God; through Jesus Christ Thy Son our Lord. Amen.","note":"A prayer to the Holy Spirit for those in sorrow, asking for light in every dark place of the heart.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/213"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Anselm died 1109; public domain.","denom":[]},{"id":"pray-chain-all-families-of-the-earth","title":"The God of All Families of the Earth","by":"Lawrence Tuttiett","year":1913,"trad":["christian"],"type":"prayer","occasion":["wedding","home","blessing"],"text":"O God, the God of all families of the earth, we call to mind before Thy Throne of grace Thy servants whom Thou hast this day knit together in holy matrimony. Pour down upon them the continual dew of Thy blessing; keep them from all dangers and adversities, and fill their home with love, joy, and peace. Be pleased, merciful Father, so to order the events of their lives that they may with one heart rejoice in the knowledge of Thy love, and with one mouth give thanks unto Thee for what Thou hast done for them; and finally, when the changes of this life are over, may they sit down together at the Marriage Supper of the Lamb, and serve Thee together in Thy glorious Kingdom; through the merits of our Lord and Saviour Jesus Christ. Amen.","note":"A prayer for a couple on their wedding day, that their home be filled with love, joy, and peace.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/206"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Tuttiett died 1897; public domain.","denom":[]},{"id":"pray-chain-comfort-in-sorrow","title":"A Comfort in Sorrow, a Strength in Need","by":"Richard Meux Benson","year":1913,"trad":["christian","episcopal"],"type":"prayer","occasion":["wedding","blessing"],"text":"O Lord Jesus Christ, Who hast vouchsafed to be the Husband of Thy Church, binding Thy people unto Thyself in the mysterious unity of a nature renewed by the Holy Ghost; have mercy upon those who are recently married, and grant that they, realizing that mutual love which Thou hast ordained to be an image of the love between Thyself and Thy people, may be found each to the other a comfort in sorrow, a strength in need, a counsellor in perplexity, a companion in every enjoyment; and having shared together Thy blessings upon earth, may attain to the blessing of Thy Heavenly Feast in the satisfaction of Thy perfect love, Who livest and reignest with the Father and the Holy Ghost, one God, world without end. Amen.","note":"A prayer for a newly married couple, that each be to the other a comfort, a strength, a counsellor, and a companion.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/206"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Benson died 1915; public domain.","denom":[]},{"id":"pray-chain-build-thou-their-home","title":"Build Thou for Them Their Home","by":"William Boyd Carpenter","year":1913,"trad":["christian"],"type":"prayer","occasion":["wedding","home","blessing"],"text":"O Lord God of our fathers, Giver of life and love, give Thy blessing to those whom Thou hast drawn together in love; surround them with Thy protecting care; build Thou for them their home; make it to be the abode of light and love. May all that is pure, tender and true, grow up under its shelter; may all that hinders godly union and concord, be driven far from it. Make it the centre of fresh, sweet, and holy influence. Give them wisdom for life, and discretion in the guidance of their affairs. Let Thy Fatherly hand ever be over them, and Thy Holy Spirit ever be with them. O Lord, bless them and theirs, and grant them to inherit Thine everlasting Kingdom; through Jesus Christ our Lord. Amen.","note":"A blessing for a new household, that it be an abode of light and love.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/206"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Carpenter died 1918; public domain.","denom":[]},{"id":"pray-chain-issues-of-life","title":"On the Birth of a Child","by":"William Boyd Carpenter","year":1913,"trad":["christian"],"type":"prayer","occasion":["birth","gratitude","home"],"text":"O Lord God, in Whose hands are the issues of life, we thank Thee for Thy gifts to us at this time. We thank Thee for the life given, and the life preserved. And as Thou hast knit together life and love in one fellowship, so we pray Thee to grant that with this fresh gift of life to us, there may be given an increase of love one to another. Grant that the presence of weakness may awaken our tenderness, enable us to minister to the little one that has been given to us in all lovingness, wisdom, and fidelity; and grant that he may live as Thy child, and may serve this generation according to Thy will; through Jesus Christ our Lord. Amen.","note":"A family's thanksgiving when a child is born, asking that new life bring new love.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/207"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Carpenter died 1918; public domain.","denom":[]},{"id":"pray-chain-happy-years","title":"Many and Happy Years","by":"Traditional, Gelasian Sacramentary","year":1913,"trad":["christian","catholic"],"type":"prayer","occasion":["celebration","birth","blessing"],"text":"Almighty and everlasting God, the Maker of all creation, mercifully hear our prayers, and grant many and happy years to Thy servant whose birthday it is, that he may spend all his life so as to please Thee; through Jesus Christ our Lord. Amen.","note":"An ancient birthday prayer asking many and happy years for the one celebrating.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/207"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); from the Gelasian Sacramentary, about the seventh century; public domain.","denom":[]},{"id":"pray-chain-travellers","title":"For Travellers","by":"Traditional, Gelasian Sacramentary","year":1913,"trad":["christian","catholic"],"type":"prayer","occasion":["blessing","daily"],"text":"O God, Who bestowest Thy mercy at all times on them that love Thee, and in no place art distant from those that serve Thee, direct the ways of Thy servants in Thy will, that, having Thee for their Protector and Guide, they may walk without stumbling in the paths of righteousness: through Jesus Christ our Lord. Amen.","note":"An ancient prayer for those setting out on a journey.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/208"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); from the Gelasian Sacramentary, about the seventh century; public domain.","denom":[]},{"id":"pray-chain-lord-of-love","title":"For Those Far Away","by":"William Boyd Carpenter","year":1913,"trad":["christian"],"type":"prayer","occasion":["blessing","home","comfort"],"text":"O Lord of Love, Who art not far from any of Thy children, watch with Thy care those who are far away from us; be Thou about their path; be Thou within their hearts; be Thou their defence upon their right hand; give them unfailing trust in Thee; grant them power against temptation; qualify them for whatever task Thou givest them to do; deliver them from the snares of setting duty aside; make it their joy to do Thy will. Let not distance break the bonds of love which bind them to us and to Thee, but knit us closer in Thy love; for the sake of Jesus Christ our Lord. Amen.","note":"A prayer for absent family and friends, that distance never break the bonds of love.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/208"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Carpenter died 1918; public domain.","denom":[]},{"id":"pray-chain-place-in-our-hearts","title":"All Who Have a Place in Our Hearts","by":"John Hunter","year":1913,"trad":["christian","ucc"],"type":"prayer","occasion":["blessing","gratitude","home"],"text":"Almighty God, by Whose goodness we were created, and Whose mercies never fail; we commend to Thee all who have a place in our hearts and sympathies; all who are joined to us by the sacred ties of kindred, friendship, and love; all little children who are dear to us; all who help us to a faithful life and whose spirit turn our duties into love; keep them both outwardly in their bodies and inwardly in their souls, and pour upon them the continual dew of Thy blessing; through Jesus Christ our Lord. Amen.","note":"A prayer for everyone we love: family, friends, and the little children dear to us.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/209"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Hunter, a Congregational minister, died 1917; public domain.","denom":[]},{"id":"pray-chain-near-us-to-defend-us","title":"Near Us to Defend Us","by":"Traditional, tenth century","year":1913,"trad":["christian","catholic"],"type":"blessing","occasion":["blessing","daily","peace"],"text":"May our Lord Jesus Christ be near us to defend us, within us to refresh us, around us to preserve us, before us to guide us, behind us to justify us, above us to bless us. Who liveth and reigneth with the Father and the Holy Ghost, God for evermore. Amen.","note":"An encircling blessing from the tenth century, asking Christ to be near, within, around, before, behind, and above.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/223"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); a tenth century blessing; public domain.","denom":[]},{"id":"pray-chain-lead-us-when-we-go","title":"Lead Us When We Go","by":"Traditional","year":1913,"trad":["christian"],"type":"blessing","occasion":["blessing","evening","peace"],"text":"May the Lord lead us when we go, and keep us when we sleep, and talk with us when we wake; and may the peace of God, which passeth all understanding, keep our hearts and minds in Jesus Christ our Lord. Amen.","note":"A closing blessing for going out, for sleep, and for waking, drawing on Proverbs 6:22.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/223"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); source not named by the compiler; public domain.","denom":[]},{"id":"pray-chain-cheerfulness","title":"The Comfort of Patience","by":"Rowland Williams","year":1913,"trad":["christian","episcopal"],"type":"prayer","occasion":["healing","comfort","peace"],"text":"O God, Who makest cheerfulness the companion of strength, but apt to take wings in time of sorrow, we humbly beseech Thee that if, in Thy sovereign wisdom, Thou sendest weakness, yet for Thy mercy's sake deny us not the comfort of patience. Lay not more upon us, O heavenly Father, than Thou wilt enable us to bear; and since the fretfulness of our spirits is more hurtful than the heaviness of our burden, grant us that heavenly calmness which comes of owning Thy hand in all things, and patience in the trust that Thou doest all things well; through Jesus Christ. Amen.","note":"A prayer in weakness or long illness, asking for heavenly calm and patient trust.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/211"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); Williams died 1870; public domain.","denom":[]},{"id":"pray-chain-tender-affection","title":"For One Who Is Sick","by":"Traditional, Gelasian Sacramentary","year":1913,"trad":["christian","catholic"],"type":"prayer","occasion":["healing","comfort"],"text":"O God, Who ever governest Thy creatures with tender affection, incline Thine ear to our supplications, and graciously regard Thy servant who is suffering from bodily sickness, and visit him with Thy salvation, and bestow the medicine of heavenly grace; through Jesus Christ our Lord. Amen.","note":"An ancient prayer for someone suffering in body, asking for the medicine of heavenly grace.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/210"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); from the Gelasian Sacramentary, about the seventh century; public domain.","denom":[]},{"id":"pray-chain-lord-bless-us-and-keep-us","title":"The Lord Be with Us Day and Night","by":"Traditional","year":1913,"trad":["christian"],"type":"blessing","occasion":["blessing","evening","daily"],"text":"The Lord bless us and keep us. The Spirit of the Lord cleanse and purify our inmost hearts, and enable us to shun all evil. The Lord enlighten our understandings and cause the Light of His Truth to shine into our hearts. The Lord fill us with faith and love towards Him. The Lord be with us day and night in our coming in and going out, in our sorrow and in our joy. And bring us at length into His eternal rest. Amen.","note":"A closing benediction for family prayers, for coming in and going out, in sorrow and in joy.","voice":"brian","source":{"name":"Selina Fitzherbert Fox, A Chain of Prayer Across the Ages: Forty Centuries of Prayer (1913), Internet Archive","url":"https://archive.org/details/cihm_81070/page/223"},"rights":"pd","pd":"Printed in A Chain of Prayer Across the Ages (1913); source not named by the compiler; public domain.","denom":[]},{"id":"pray-hapgood-physician-of-souls","title":"From the Prayer of Holy Unction: Physician of Our Souls and Bodies","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"prayer","occasion":["healing","comfort","gratitude"],"text":"We thank thee, O Lord our God, who art good and lovest mankind, the Physician of our souls and bodies, who painlessly hast borne our infirmities, by whose stripes we have all been healed, thou good Shepherd, who didst come to seek the wandering sheep; who givest consolation to the faint-hearted, and life unto those who are broken of heart; who didst heal the flow of the woman who had had an issue of blood twelve years; who didst free the daughter of the Canaanitish woman from the cruel demon; who forgavest their debt unto the two debtors, and didst grant remission of sins unto the woman that was a sinner; who didst vouchsafe healing unto the Paralytic, and likewise the remission of his sins; who didst justify the Publican by thy word, and didst accept the Thief at his last confession; who takest away the sins of the world, and wast nailed to the Cross.","note":"The opening of a prayer from the Orthodox anointing of the sick, recalling Christ's healings.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/355"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-children-beginning-instruction","title":"For Children Beginning Their Lessons","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"litany","occasion":["blessing","daily","home"],"text":"That he will send down upon these children the spirit of wisdom and understanding, and will open their minds and their lips, and enlighten their hearts, unto the receiving of precepts of good instruction, let us pray to the Lord.\nThat he will implant in their hearts his godly fear, which is the beginning of wisdom, and will thereby expel from their hearts the turbulence of youth, and enlighten their minds, that they may turn aside from evil and do that which is good.\nThat he will open their minds to receive, and to understand, and to remember all instruction which is good and profitable for the soul.\nThat he will grant them the wisdom which abideth with his throne, and will implant it in their hearts, so that he may teach them that which is well-pleasing in his sight.\nThat he will prosper them in wisdom and in stature, to the glory of God.\nThat they may have a wise and virtuous life, and prosperity in the Orthodox faith, and may be a joy and consolation to their parents, and pillars of the Orthodox-Catholic Church.","note":"Petitions from the Orthodox service of prayer when children begin their schooling, each answered Lord, have mercy.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/520"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-crown-of-the-year","title":"Bless the Crown of the Coming Year","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"litany","occasion":["season","peace","nature","celebration"],"text":"That thou wilt bless the crown of the coming year with thy goodness, and quench within us all enmities, discords and civil strife; that thou wilt give us peace, love steadfast and unfeigned, as also a decorously ordered and virtuous life, we beseech thee, O all-gracious Lord: hearken, and have mercy.\n\nThat thou wilt give rain in due season, both the early and the latter rains, fruitful dew, temperate and healthful breezes; and that thou wilt illumine with the warmth of the sun, we beseech thee, O all-bountiful Lord: hearken, and have mercy.","note":"Two petitions from the Orthodox thanksgiving at the New Year, for peace and for a good season.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/538"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-hapgood-after-communion","title":"Thanksgiving after Holy Communion","by":"Traditional","tr":"Isabel F. Hapgood","year":1906,"trad":["orthodox","christian"],"denom":["eastern"],"type":"prayer","occasion":["gratitude","daily","hope"],"text":"I thank thee, O Lord my God, that thou hast not rejected me, a sinner, but hast deemed me worthy to become a partaker of thy Holy Things. I thank thee that thou hast graciously granted unto me, though unworthy, to receive thy pure and heavenly Gifts.\n\nBut, O Master who lovest mankind, who for our sake didst die, and didst rise again, and hast graciously bestowed upon us these terrible and life-giving Mysteries, for the blessing and sanctification of our souls and bodies: Vouchsafe that they may be efficacious for me also unto the healing of my soul and body, unto the averting of everything contrary thereto; unto the enlightenment of the eyes of my heart; unto the peace of my spiritual powers; unto faith invincible; unto love unfeigned; unto the fulfilling of wisdom; unto the keeping of thy commandments; unto the increase of thy divine grace and the attainment of thy kingdom: that by thee preserved in thy holiness I may ever bear in mind thy grace, and live not unto myself, but unto thee, our Master and Benefactor.\n\nAnd so, this life ended in the hope of life everlasting, I may come unto that rest eternal, where the voice of those who keep high festival ceaseth never, and where endless is the sweetness of those who behold the beauty inexpressible of thy countenance. For thou art the true desire and the happiness unutterable of those who love thee, O Christ our God, and every created being shall laud thee unto ages of ages. Amen.","note":"Said after receiving Communion in the Orthodox Divine Liturgy; its close is also a beautiful prayer for the life to come.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic (Greco-Russian) Church (1906), Internet Archive","url":"https://archive.org/details/cu31924029363128/page/115"},"rights":"pd","pd":"Published 1906; Hapgood died 1928; public domain."},{"id":"pray-key-father-and-mother-deceased","title":"For a Father and Mother Who Have Died","by":"Traditional, Roman Missal","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["grief","funeral","comfort"],"text":"O God, who hast commanded us to honor our father and mother, have compassion, in thy mercy, on the souls of my father and mother, and forgive them their sins, and grant that we may meet in the joy of eternal bliss.","note":"The Church's prayer for one's own parents after their death, said at Mass and on anniversaries.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/594"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]},{"id":"pray-key-for-a-journey","title":"In the Way of Peace","by":"Traditional, Roman Breviary","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["blessing","daily"],"text":"In the way of peace and prosperity may the Lord, the almighty and merciful, direct our steps. And may the Angel Raphael accompany us on the way, that we may return to our home in peace, safety, and joy.\n\nO God, who madest the sons of Israel to walk with dry feet through the midst of the sea, and who didst open to the three Magi, by the guiding of a star, the way that led to thee; grant to us, we beseech thee, a prosperous journey, and a time of tranquillity, that, attended by thy holy angel, we may happily arrive at that place whither we are journeying, and finally at the haven of eternal salvation.","note":"The Itinerarium, the Church's prayer before setting out on a journey.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/128"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]},{"id":"pray-key-for-our-friends","title":"For Our Friends","by":"Traditional, Roman Missal","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["healing","blessing","daily"],"text":"O God, who hast poured the gift of charity, by the grace of the Holy Ghost, into the hearts of the faithful: grant to thy servants (here name those you pray for), for whom we implore thy mercy, health of mind and body; that loving thee with all their strength, they may accomplish those things which are pleasing to thee.","note":"A prayer naming friends before God and asking health of mind and body for them.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/129"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]},{"id":"pray-key-give-me-grace","title":"Give Me Grace, O Lord","by":"Traditional","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["morning","daily","blessing"],"text":"Give me grace, O Lord, to do what thou commandest, and command what thou pleasest. Give me grace to suffer what thou permittest, and permit what thou pleasest. The blessing of God Almighty, Father, Son, and Holy Ghost, descend upon me, and dwell in my heart forever. Amen.","note":"A short morning offering that ends with a blessing on the one who prays.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/48"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]},{"id":"pray-key-universal-prayer","title":"From the Universal Prayer","by":"Attributed to Pope Clement XI","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["daily","morning"],"text":"O my God, I believe in thee, do thou strengthen my faith. All my hopes are in thee, do thou secure them. I love thee with my whole heart, teach me to love thee daily more and more. I am sorry that I have offended thee: do thou increase my sorrow.\n\nI adore thee as my first beginning. I aspire after thee as my last end. I give thee thanks as my constant Benefactor: I call upon thee as my sovereign Protector.\n\nVouchsafe, O my God, to conduct me by thy wisdom, to restrain me by thy justice, to comfort me by thy mercy, to defend me by thy power. To thee I desire to consecrate all my thoughts, words, actions, and sufferings; that henceforward I may think of thee; speak of thee, willingly refer all my actions to thy greater glory, and suffer willingly whatever thou shalt appoint.\n\nLord, I desire that in all things thy will may be done, because it is thy will, and in the manner thou willest.","note":"The opening of a long prayer for all things needful, printed in Catholic prayer books since the 1700s.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/365"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain. Prayer attributed to Clement XI, who died 1721.","denom":[]},{"id":"pray-penington-shooting-up-of-the-corn","title":"As the Shooting Up of the Corn","by":"Isaac Penington","year":1796,"trad":["quaker","christian"],"type":"reflection","occasion":["hope","comfort","healing"],"text":"If thy heart come to feel the seed of God, and to wait upon him in the measure of his life, he will be tender of thee as a father of his child, and his love will be naturally breaking forth towards thee. This is the end of all his dealings with thee, to bring thee hither, to make thee fit and capable of entering and abiding here. And he hath changed, and doth change thy spirit daily; though it be as the shooting up of the corn, whose growth cannot be discerned at present by the most observing eye, but it is very manifest afterwards that it hath grown.\n\nBut wait to feel the relieving measure of life, and heed not distressing thoughts, when they arise ever so strongly in thee; nay, though they have entered thee, fear them not, but be still a while, not believing in the power which thou feelest they have over thee, and it will fall on a sudden.","note":"From a letter of encouragement to a friend in distress, on growth that is slow, hidden, and real.","voice":"brian","source":{"name":"Letters of Isaac Penington (Philadelphia, 1859), Letter I, to Bridget Alley, Internet Archive","url":"https://archive.org/details/peningtonsletter00peniuoft"},"rights":"pd","pd":"Written before 1679, first published 1796; Penington died 1679; public domain.","denom":[]},{"id":"pray-key-for-the-sick","title":"For Those Who Are Sick","by":"Traditional, Roman Missal","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["healing","comfort"],"text":"O Almighty and eternal God, the perpetual salvation of them that believe, hear us for thy sick servants, for whom we humbly crave the help of thy mercy, that their health being restored to them, they may render thanks to thee in thy Church.","note":"The Church's collect for the sick, asking that health be restored and thanks be given.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/128"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]},{"id":"pray-key-for-the-living","title":"The Right Hand of Thy Heavenly Succor","by":"Traditional, Roman Missal","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["blessing","daily"],"text":"Extend unto thy faithful, O Lord, the right hand of thy heavenly succor, that they may seek thee with all their hearts, and obtain of thy mercy whatever is necessary to their condition.","note":"A short collect for all the living, that each may seek God and find what they need.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/129"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]},{"id":"pray-key-i-commend","title":"To Thee, O Lord, I Commend","by":"Traditional","year":1874,"trad":["catholic","christian"],"type":"prayer","occasion":["morning","home","daily"],"text":"I adore and glorify thee, O blessed Trinity, God Almighty, Father, Son, and Holy Ghost, I offer myself to thy divine Majesty; humbly beseeching thee to take from me, and from all thy faithful, whatever displeases thee; and to give us that which is grateful in thy sight; grant that we may here do what thou commandest, and hereafter receive what thou promisest.\n\nTo Thee, O Lord, I commend my soul and body [my wife and children, my father and mother, my brothers and sisters], my kinsfolk, benefactors, and friends, all my nearest and dearest relatives, and all those for whom I am in any way bound to offer up my prayers. To thee I commend the Holy Catholic Church. To thee I commend this country and its rulers. Grant, O Lord, that all may know thee, all may honor and reverence thee, all may love thee, and be loved by thee.","note":"A morning commendation of oneself, one's family, friends, and all people into God's care.","voice":"brian","source":{"name":"The Key of Heaven, or A Manual of Prayer (Baltimore, 1874), Internet Archive","url":"https://archive.org/details/keyofheavenorman00miln/page/48"},"rights":"pd","pd":"Printed 1874; traditional Catholic prayers in an English translation in use by the 1800s; public domain.","denom":[]}];
